steps.script:
var tm = tree.root.get_node("/root/TutorialManager")
var saved = GameState.state.get("units", {}).duplicate(true)
var was_web = SaveLoadManager.is_web_platform
GameState.state["units"] = {}
SaveLoadManager.is_web_platform = true
var r = tm._load_fixture("nonexistent_fixture")
SaveLoadManager.is_web_platform = was_web
GameState.state["units"] = saved
return r

var l = tree.root.get_node_or_null("/root/Main/HUD_Right/VBoxContainer/MovementScrollContainer/MovementPanel/Section1_UnitList/MovementUnitList")
if l == null:
	return false
var texts = []
for i in range(l.item_count):
	texts.append(str(l.get_item_text(i)))
return l.item_count > 0 and "|".join(texts).contains("Battlewagon")

var o = tree.root.get_node("/root/TutorialOverlay")
var t = str(o.current_body_text())
return t.contains("Game Log") and t.contains("Dice Log") and t.contains("empty")

var lbl = tree.root.get_node_or_null("/root/Main/HotkeyHelpOverlay")
if lbl == null:
	return ""
var hit = ""
var stack = [lbl]
while stack.size() > 0:
	var n = stack.pop_back()
	for c in n.get_children():
		stack.append(c)
	if n is Label and str(n.name) == "PadRouteHint":
		hit = str(n.text)
return hit

var rt = tree.root.get_node_or_null("/root/TutorialOverlay/InstructorCard/Margin/VBox/BodyText")
if rt == null:
	return "<no BodyText>"
return rt.get_parsed_text().contains("top right-hand corner")

var mc = tree.current_scene.movement_controller
var models = GameState.get_unit("U_GRETCHIN_T").get("models", [])
var alive = 0
for m in models:
	if m.get("alive", true):
		alive += 1
return alive > 1 and mc.selected_models.size() == alive and str(mc.selection_mode) == "MULTI"

var md = PhaseManager.current_phase_instance.get_active_move_data("U_GRETCHIN_T")
var staged := {}
for sm in md.get("staged_moves", []):
	staged[str(sm.get("model_id", ""))] = true
var models = GameState.get_unit("U_GRETCHIN_T").get("models", [])
var alive = 0
for m in models:
	if m.get("alive", true):
		alive += 1
return alive > 1 and staged.size() == alive

var md = PhaseManager.current_phase_instance.get_active_move_data("U_GRETCHIN_T")
var d := {}
for sm in md.get("staged_moves", []):
	d[str(sm.get("model_id", ""))] = str(sm.get("dest"))
InputDeviceManager.set_meta("pre_drop_dests", d)
return d.size()

var mc = tree.current_scene.movement_controller
var md = PhaseManager.current_phase_instance.get_active_move_data("U_GRETCHIN_T")
var pre = InputDeviceManager.get_meta("pre_drop_dests")
var landed := {}
var stayed := {}
for sm in md.get("staged_moves", []):
	var mid = str(sm.get("model_id", ""))
	if str(sm.get("dest")) != str(pre.get(mid, "")):
		landed[mid] = true
	else:
		stayed[mid] = true
var sel := {}
for m in mc.selected_models:
	sel[str(m.get("model_id", ""))] = true
if landed.is_empty() or stayed.is_empty():
	return "not a partial drop: landed=%d stayed=%d" % [landed.size(), stayed.size()]
if sel.size() != stayed.size():
	return "selection %d != leftovers %d" % [sel.size(), stayed.size()]
for k in stayed:
	if not sel.has(k):
		return "leftover %s is not selected" % k
return "ok"
